function timelineFeedback(text){$('closing-email-feedback').textContent=text;const preview=$('timeline-email-feedback');if(preview)preview.textContent=text}
function copyPicture(){
 const success='Timeline copied. Open Mail and paste between the CLOSING TIMELINE SUMMARY markers with ⌘V (Mac) or Ctrl+V (Windows).';
 const fallback=()=>{
  const printable=timelineEmailTable();
  if(navigator.clipboard?.writeText){
   navigator.clipboard.writeText(printable).then(()=>timelineFeedback('Your browser cannot copy the formatted image, so the timeline text was copied. Paste it into Mail.')).catch(()=>{
    window.prompt('Copy these milestone dates and paste them into Mail:',printable);
    timelineFeedback('Your browser blocked image copying. Select and copy the displayed timeline text to paste in Mail.');
   });
  }else{
   window.prompt('Copy these milestone dates and paste them into Mail:',printable);
   timelineFeedback('To paste the formatted image, use a current browser that supports copying images.');
  }
 };
 if(!navigator.clipboard||!window.ClipboardItem){fallback();return}
 try{
  const png=new Promise((resolve,reject)=>emailPicture().toBlob(b=>b?resolve(b):reject(Error('Image unavailable')),'image/png'));
  navigator.clipboard.write([new ClipboardItem({'image/png':png})])
    .then(()=>timelineFeedback(success))
    .catch(fallback);
 }catch(e){fallback()}
}

