function timelineEmailTable(){
 const items=collect();
 const head=['BUYER CLOSING TIMELINE — CONTRACT MILESTONES','', 'No.  Task / Milestone  |  Days  |  Due date','────────────────────────────────────────'];
 const rowsText=items.map((r,i)=>{
  const due=r.date?timelineShortDate(r.date):'To be confirmed';
  const days=r.days!==''&&r.days!=null?String(r.days):'—';
  const status=r.status==='done'?' [Done]':r.status==='na'?' [N/A]':'';
  return String(i+1).padStart(2,'0')+'. '+String(r.name||'Milestone')+'  |  '+days+'  |  '+due+status;
 });
 return [...head,...rowsText,'────────────────────────────────────────','Please confirm all due dates and notice requirements against the signed contract.'].join('\n');
}
